import{_ as o,l,o as e,c as n,v as t,p as s,x as i,d as p,i as h,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"钌覆盖层","description":"","frontmatter":{"title":"钌覆盖层","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/ruthenium-capping.md","filePath":"litho/ruthenium-capping.md","lastUpdated":1789023840000}'),u={name:"litho/ruthenium-capping.md"};function c(m,a,_,E,B,A){const r=l("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="钌覆盖层" tabindex="-1">钌覆盖层 <a class="header-anchor" href="#钌覆盖层" aria-label="Permalink to &quot;钌覆盖层&quot;">​</a></h1><div class="epigraph"><p>Mo/Si 怕氧、怕氢、怕碳。几纳米钌当帽：保住布拉格周期，自己尽量少吃带内反射率，还要允许氢刻锡。</p><footer>—— 据 Bajt 等对 Ru 帽层；Bakshi 多层与表面化学</footer></div><p><a href="/litho/euv-phase-shift-mask">上一课</a>无论二元还是相移，工作面都是多层顶。缺口是这层顶在真空、氢和 EUV 下怎么活：量产公开的覆盖层是钌（Ru）。黑边要把场外多层弄黑，留给[下一课](/litho/black-border）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>硅顶层在空气或残余水里氧化，周期膨胀、对比下降；氢自由基可以刻碳也可以攻击错误的帽；锡若落到无帽界面，清洗会连硅一起伤。需要一层薄帽：13.5 nm 吸收尽量小、连续、抗氧、在氢等离子体中相对惰，并且不把 MSFR 抬起来。钌是公开选中的折中，不是「最不吸收的元素」。</p><p>缺口是帽层合同，不是再讲 Mo/Si 周期公式。掩模空白和投影镜都用帽，但掩模还要在上面刻吸收体、修缺陷、装 pellicle，帽的针孔就是相位坑。</p><p><span class="marginnote">帽层厚度是反射率与保护的折中，公开量级是数纳米。太厚，峰值 \\(R\\) 掉；太薄，针孔和扩散。不要把某张 TEM 照片的厚度当全球规格。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>沉积：在多层完成后加 Ru，有时带超薄阻挡以免 Ru 与 Si 互扩散。掩模厂再在帽上沉积吸收体并图形化，刻蚀必须停在帽上或可控地微侵，不能把布拉格堆挖穿——除非故意做黑边。氢清洗假设帽在，收集镜课已经用过这个假设。</p><p>计量：峰值 \\(R\\)、氧化前后差、氢暴露后的起泡与应力、缺陷密度。针孔在光化检验上表现为相位缺陷，打印阈值随照明变。</p><h3 id="大气暴露是掩模帽的额外税" tabindex="-1">大气暴露是掩模帽的额外税 <a class="header-anchor" href="#大气暴露是掩模帽的额外税" aria-label="Permalink to &quot;大气暴露是掩模帽的额外税&quot;">​</a></h3><p>投影镜几乎不离开真空；掩模要进出盒、检验机和大气。钌减缓氧化，但不能无限次暴露。帽上的自然氧化层改一点 n、k 和应力，反复进出后 \\(R\\) 和相位指纹会走。存储与搬运的惰性气氛是帽层合同的一部分，不是设施附录。</p>',12)),(e(),s(d,null,{default:i(()=>[h(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ML%5B%22Mo%2FSi%20%E5%91%A8%E6%9C%9F%22%5D%20--%3E%20RU%5B%22Ru%20%E5%B8%BD%22%5D%0A%20%20RU%20--%3E%20PROT%5B%22%E6%8A%97%E6%B0%A7%20%2F%20%E6%8A%97%E6%B0%A2%E7%AA%97%E5%8F%A3%22%5D%0A%20%20RU%20--%3E%20R%5B%22%E7%95%A5%E7%89%BA%E7%89%B2%E5%B8%A6%E5%86%85%20R%22%5D%0A%20%20ABS%5B%22%E5%90%B8%E6%94%B6%E4%BD%93%22%5D%20--%3E%20RU%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Ru 在 13.5 nm 的光学常数允许薄层仍有可接受透过（作为帽，不是作为吸收体）。它减缓氧向硅的扩散，并提供氢刻锡时的化学终点：SnH₄ 走，Ru 尽量留。Bajt 等的多层帽层工作表明，帽同时改应力和轻微相移——吸收体 + 帽 + 多层是同一块电磁物。氢植入起泡若发生在帽–多层界面，MSFR 和局部相位一起坏，氢等离子体课的不可逆项在掩模上同样成立。</p><p><span class="marginnote">掩模帽与投影镜帽配方不必相同：掩模还要兼容吸收体刻蚀和大气暴露；投影镜几乎不离开真空。不要写成一种 Ru 膜打天下。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写场边缘如何把多层蚀穿做成黑边，下一课才写。不重写收集镜清洗流量。帽的针孔按相位缺陷管，按吸收体缺陷管会漏检。出处：Bajt Ru capping；Bakshi；Madey 表面化学；氢等离子体课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>钌帽保护 Mo/Si 对抗氧和氢，并给刻蚀一个可停的表面，代价是一点 \\(R\\) 和潜在针孔。</li><li>吸收体、相移层和缺陷都坐在帽上，帽是掩模电磁的一部分。</li><li>下一课：场与场之间那圈「不该反光」的黑边。</li><li>出处：Bajt；Bakshi；ASML/SEMATECH 帽层公开讨论。</li></ul>',7))])}const S=o(u,[["render",c]]);export{f as __pageData,S as default};
